Input: {"question": "When was Austin City Hall built?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0146-6f444170c228:d00", "start": 0, "end": 71, "text": "Austin City Hall (Austin, Nevada) The Austin City Hall, at 90 South St."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0146-6f444170c228:d00", "start": 72, "end": 200, "text": "in Austin, Nevada, was built in 1866, when Austin was prosperous as a new silvermining city, and served as a city hall and jail."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0146-6f444170c228:d00", "start": 201, "end": 304, "text": "It has also been known as Austin Station House, as Austin American Legion Hall, and as Austin VFW Hall."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0146-6f444170c228:d00", "start": 305, "end": 371, "text": "It was listed on the National Register of Historic Places in 2003."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0146-6f444170c228:d00", "start": 372, "end": 492, "text": "It was deemed significant for serving Austin during most of the 1864-1881 period during which Austin was legally a city."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0146-6f444170c228:d00", "start": 493, "end": 565, "text": "The building was transferred to the local Knights of Pythias chapter and"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0146-6f444170c228:d01", "start": 0, "end": 15, "text": "entry is 1866 ."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0146-6f444170c228:d01", "start": 16, "end": 26, "text": "Location ."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0146-6f444170c228:d01", "start": 27, "end": 57, "text": "39° 29.529′ N , 117° 4.315′ W."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0146-6f444170c228:d01", "start": 58, "end": 107, "text": "Marker is in Austin , Nevada , in Lander County ."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0146-6f444170c228:d01", "start": 108, "end": 185, "text": "It is at the intersectio